module casino_profit (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [15:0] x,\n    input wire [15:0] p,\n    output reg [31:0] profit,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] S_IDLE         = 4'd0;\n    localparam [3:0] S_INIT         = 4'd1;\n    localparam [3:0] S_RESET_K      = 4'd2;\n    localparam [3:0] S_LOAD_PROB    = 4'd3;\n    localparam [3:0] S_COMPUTE_PROFIT = 4'd4;\n    localparam [3:0] S_NEXT_K       = 4'd5;\n    localparam [3:0] S_UPDATE_MAX   = 4'd6;\n    localparam [3:0] S_NEXT_N       = 4'd7;\n    localparam [3:0] S_DONE         = 4'd8;\n\n    // Parameters\n    localparam MAX_N = 8'd64;\n    localparam Q16_16 = 32'd65536;\n    \n    // Internal registers\n    reg [3:0]   state;\n    reg [7:0]   n;\n    reg [7:0]   k;\n    reg [31:0]  prob;\n    reg [31:0]  accum;\n    reg [31:0]  max_profit;\n    reg [31:0]  p_frac;\n    reg [31:0]  one_minus_p_frac;\n    reg [31:0]  x_frac;\n    reg [15:0]  p_scale;\n\n    // Fixed-point multiplication function\n    function [31:0] mul_fixed;\n        input [31:0] a;\n        input [31:0] b;\n        reg [63:0] temp;\n        begin\n            temp = a * b;\n            mul_fixed = temp[47:16];  // Middle 32 bits for Q16.16\n        end\n    endfunction\n\n    // Compute profit function\n    function [31:0] compute_profit;\n        input [7:0] k_val;\n        input [7:0] n_val;\n        reg [15:0] net;\n        reg [15:0] positive_net;\n        reg [31:0] refund;\n        begin\n            net = (k_val << 1) - n_val;  // 2*k - n\n            \n            if (net[15] == 1'b0) begin  // positive or zero\n                compute_profit = net << 16;\n            end else begin\n                positive_net = -net;  // magnitude of loss\n                refund = mul_fixed(x_frac, positive_net << 16);\n                compute_profit = {net[15], 15'd0, refund[30:16]};  // Save sign bit\n            end\n        end\n    endfunction\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            profit <= 32'd0;\n            n <= 8'd0;\n            k <= 8'd0;\n            prob <= 32'd0;\n            accum <= 32'd0;\n            max_profit <= 32'd0;\n            p_frac <= 32'd0;\n            one_minus_p_frac <= 32'd0;\n            x_frac <= 32'd0;\n            p_scale <= 16'd0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        p_frac <= {p, 16'd0};  // p * 65536\n                        one_minus_p_frac <= {16'd65535 - p + 1'b1, 16'd0};  // (1-p) * 65536\n                        x_frac <= x * 16'd65536 / 16'd100;  // x/100 * 65536\n                        state <= S_INIT;\n                    end\n                end\n\n                S_INIT: begin\n                    max_profit <= 32'h80000000;  // Smallest negative value\n                    n <= 8'd1;\n                    state <= S_RESET_K;\n                end\n\n                S_RESET_K: begin\n                    k <= 8'd0;\n                    prob <= Q16_16;  // Probability = 1.0\n                    accum <= 32'd0;\n                    state <= S_LOAD_PROB;\n                end\n\n                S_LOAD_PROB: begin\n                    state <= S_COMPUTE_PROFIT;\n                end\n\n                S_COMPUTE_PROFIT: begin\n                    accum <= accum + mul_fixed(prob, compute_profit(k, n));\n                    if (k == n) begin\n                        state <= S_UPDATE_MAX;\n                    end else begin\n                        state <= S_NEXT_K;\n                    end\n                end\n\n                S_NEXT_K: begin\n                    k <= k + 8'd1;\n                    prob <= mul_fixed(mul_fixed(prob, p_frac) * (n - k + 8'd1), Q16_16) / ((k + 8'd1) * one_minus_p_frac);\n                    state <= S_LOAD_PROB;\n                end\n\n                S_UPDATE_MAX: begin\n                    if (accum > max_profit) begin\n                        max_profit <= accum;\n                    end\n                    \n                    if (n == MAX_N) begin\n                        state <= S_DONE;\n                    end else begin\n                        n <= n + 8'd1;\n                        state <= S_RESET_K;\n                    end\n                end\n\n                S_DONE: begin\n                    profit <= (max_profit[31]) ? 32'd0 : max_profit;  // Clamp negative to zero\n                    done <= 1'b1;\n                    state <= S_IDLE;\n                end\n\n                default: state <= S_IDLE;\n            endcase\n        end\n    end\n\nendmodule